import json

def transform(input_grid):
    """
    Find frame bounding box, expand by 2 on all sides.
    Within expanded region: frame cells stay same, others become interior color.
    Outside: remains background.
    """
    H, W = len(input_grid), len(input_grid[0])

    # Get all non-background colors
    colors = set()
    for r in range(H):
        for c in range(W):
            if input_grid[r][c] != 0:
                colors.add(input_grid[r][c])

    # Find each color's bounding box and count
    color_counts = {}
    color_boxes = {}
    for c in colors:
        rows = [r for r in range(H) for col_c in range(W) if input_grid[r][col_c] == c]
        count = len(rows)
        if rows:
            color_counts[c] = count
            cols = [col_c for r in range(H) for col_c in range(W) if input_grid[r][col_c] == c]
            if cols:
                color_boxes[c] = (min(rows), max(rows), min(cols), max(cols))

    # Largest color region is frame (border)
    color_sorted = sorted(color_counts.items(), key=lambda x: -x[1])
    frame_color, frame_count = color_sorted[0]

    frame_min_r, frame_max_r, frame_min_c, frame_max_c = color_boxes[frame_color]

    # Interior is the second color
    if len(color_sorted) > 1:
        interior_color = color_sorted[1][0]
    else:
        interior_color = list(colors)[1]

    # Create target box by expanding frame by 2 on each side
    pad = 2
    target_r_start = max(0, frame_min_r - pad)
    target_r_end = min(H - 1, frame_max_r + pad)
    target_c_start = max(0, frame_min_c - pad)
    target_c_end = min(W - 1, frame_max_c + pad)

    # Build output
    output = [[0 for _ in range(W)] for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if target_r_start <= r <= target_r_end and target_c_start <= c <= target_c_end:
                if input_grid[r][c] == frame_color:
                    output[r][c] = frame_color
                else:
                    output[r][c] = interior_color
            else:
                output[r][c] = 0

    return output

